#include <array>
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct VmLine { std::uint16_t address; std::string text; };
struct VmResult { std::string output; bool halted; bool error; int steps; };

namespace
{
    struct Insn { std::uint8_t op; int a; int b; std::uint16_t value; std::size_t length; };

    std::size_t lengthOf(std::uint8_t op)
    {
        switch (op)
        {
        case 0x00: return 1;
        case 0x01: case 0x07: return 4;
        case 0x0E: return 2;
        default: return op <= 0x0D ? 3 : 0;
        }
    }

    std::optional<Insn> fetch(const std::vector<std::uint8_t>& p, std::size_t at)
    {
        if (at >= p.size()) return std::nullopt;
        const std::uint8_t op{ p[at] };
        const std::size_t length{ lengthOf(op) };
        if (!length || at + length > p.size()) return std::nullopt;
        Insn in{ op, 0, 0, 0, length };
        const bool jump{ op >= 0x09 && op <= 0x0C };
        if (op == 0x01 || op == 0x07) { in.a = p[at + 1]; in.value = static_cast<std::uint16_t>(p[at + 2] | (p[at + 3] << 8)); }
        else if (jump) in.value = static_cast<std::uint16_t>(p[at + 1] | (p[at + 2] << 8));
        else if (op == 0x0E) in.a = p[at + 1];
        else if (op != 0x00) { in.a = p[at + 1]; in.b = p[at + 2]; }
        if (in.a > 7 || in.b > 7) return std::nullopt;
        return in;
    }

    std::string hex(unsigned v, int digits)
    {
        static const char* const HEX{ "0123456789abcdef" };
        std::string out;
        do { out.insert(out.begin(), HEX[v & 0xF]); v >>= 4; } while (v);
        while (static_cast<int>(out.size()) < digits) out.insert(out.begin(), '0');
        return "0x" + out;
    }
}

std::vector<VmLine> disassembleVm(const std::vector<std::uint8_t>& program)
{
    static const char* const names[]{ "halt", "movi", "mov", "add", "sub", "xor", "mul", "andi", "cmp", "jmp", "je", "jne", "jl", "in", "out" };
    std::vector<VmLine> lines;
    std::size_t at{ 0 };
    while (at < program.size())
    {
        const auto in{ fetch(program, at) };
        if (!in) { lines.push_back({ static_cast<std::uint16_t>(at), "db " + hex(program[at], 2) }); ++at; continue; }
        const std::string r{ "r" + std::to_string(in->a) }, rb{ "r" + std::to_string(in->b) };
        std::string text{ names[in->op] };
        if (in->op == 0x01 || in->op == 0x07) text += " " + r + ", " + hex(in->value, 1);
        else if (in->op >= 0x09 && in->op <= 0x0C) text += " " + hex(in->value, 4);
        else if (in->op == 0x0E) text += " " + r;
        else if (in->op != 0x00) text += " " + r + ", " + rb;
        lines.push_back({ static_cast<std::uint16_t>(at), text });
        at += in->length;
    }
    return lines;
}

VmResult runVm(const std::vector<std::uint8_t>& program, const std::string& input, int maxSteps)
{
    std::array<std::uint32_t, 8> r{};
    bool eq{ false }, lt{ false };
    std::size_t pc{ 0 };
    VmResult result{ "", false, false, 0 };
    while (result.steps < maxSteps)
    {
        const auto in{ fetch(program, pc) };
        if (!in) { result.error = true; return result; }
        ++result.steps;
        std::size_t next{ pc + in->length };
        std::uint32_t& a{ r[in->a] };
        const std::uint32_t b{ r[in->b] };
        switch (in->op)
        {
        case 0x00: result.halted = true; return result;
        case 0x01: a = in->value; break;
        case 0x02: a = b; break;
        case 0x03: a += b; break;
        case 0x04: a -= b; break;
        case 0x05: a ^= b; break;
        case 0x06: a *= b; break;
        case 0x07: a &= in->value; break;
        case 0x08: eq = a == b; lt = a < b; break;
        case 0x09: next = in->value; break;
        case 0x0A: if (eq) next = in->value; break;
        case 0x0B: if (!eq) next = in->value; break;
        case 0x0C: if (lt) next = in->value; break;
        case 0x0D: a = b < input.size() ? static_cast<std::uint8_t>(input[b]) : 0u; break;
        case 0x0E: result.output += static_cast<char>(a & 0xFF); break;
        default: result.error = true; return result;
        }
        pc = next;
    }
    return result;
}

std::vector<std::string> findKeys(const std::vector<std::uint8_t>& program)
{
    std::vector<std::string> keys;
    for (int n{ 0 }; n < 10000; ++n)
    {
        std::string key{ std::to_string(n) };
        key.insert(key.begin(), 4 - key.size(), '0');
        const VmResult r{ runVm(program, key, 10000) };
        if (r.halted && r.output == "OK") keys.push_back(key);
    }
    return keys;
}

