using Bytes = std::vector<std::uint8_t>;
static const Bytes PROGRAM{
    0x01, 0x00, 0x00, 0x00, 0x01, 0x01, 0x00, 0x00, 0x01, 0x02, 0x04, 0x00, 0x01, 0x03, 0x0D, 0x00, 0x01, 0x07, 0x01, 0x00,
    0x0D, 0x04, 0x01, 0x01, 0x05, 0x30, 0x00, 0x08, 0x04, 0x05, 0x0C, 0x65, 0x00, 0x01, 0x05, 0x3A, 0x00, 0x08, 0x04, 0x05,
    0x0C, 0x2E, 0x00, 0x09, 0x65, 0x00, 0x06, 0x00, 0x03, 0x05, 0x00, 0x04, 0x07, 0x00, 0xFF, 0xFF, 0x03, 0x01, 0x07, 0x08,
    0x01, 0x02, 0x0C, 0x14, 0x00, 0x0D, 0x04, 0x01, 0x01, 0x05, 0x00, 0x00, 0x08, 0x04, 0x05, 0x0B, 0x65, 0x00, 0x01, 0x05,
    0xA4, 0xB5, 0x08, 0x00, 0x05, 0x0B, 0x65, 0x00, 0x01, 0x06, 0x4F, 0x00, 0x0E, 0x06, 0x01, 0x06, 0x4B, 0x00, 0x0E, 0x06,
    0x00, 0x01, 0x06, 0x4E, 0x00, 0x0E, 0x06, 0x01, 0x06, 0x4F, 0x00, 0x0E, 0x06, 0x00 };

TEST("disassembling the program") {
    const auto lines{ disassembleVm(PROGRAM) };
    CHECK_EQ(lines.size(), 36u);
    if (lines.size() != 36) return;
    CHECK_EQ(lines[0].text, std::string("movi r0, 0x0"));
    CHECK_EQ(lines[3].text, std::string("movi r3, 0xd"));
    CHECK_EQ(lines[5].address, 0x14);
    CHECK_EQ(lines[5].text, std::string("in r4, r1"));
    CHECK_EQ(lines[8].text, std::string("jl 0x0065"));
    CHECK_EQ(lines[15].text, std::string("andi r0, 0xffff"));
    CHECK_EQ(lines[23].text, std::string("movi r5, 0xb5a4"));
    CHECK_EQ(lines[27].text, std::string("out r6"));
    CHECK_EQ(lines[30].text, std::string("halt"));
    CHECK_EQ(lines[30].address, 0x64);
}
TEST("bad bytes in a listing") {
    const auto lines{ disassembleVm({ 0x0E, 0x08, 0xFF, 0x02 }) };
    CHECK_EQ(lines.size(), 4u);
    if (lines.size() == 4) { CHECK_EQ(lines[0].text, std::string("db 0x0e")); CHECK_EQ(lines[1].text, std::string("db 0x08")); CHECK_EQ(lines[2].text, std::string("db 0xff")); CHECK_EQ(lines[3].text, std::string("db 0x02")); }
    const auto jump{ disassembleVm({ 0x09, 0xFF, 0x01 }) };
    if (!jump.empty()) CHECK_EQ(jump[0].text, std::string("jmp 0x01ff"));
}
TEST("running the check") {
    CHECK_EQ(runVm(PROGRAM, "4271", 10000).output, std::string("OK"));
    CHECK_EQ(runVm(PROGRAM, "1234", 10000).output, std::string("NO"));
    CHECK_EQ(runVm(PROGRAM, "42a1", 10000).output, std::string("NO"));
    CHECK_EQ(runVm(PROGRAM, "42711", 10000).output, std::string("NO"));
    CHECK_EQ(runVm(PROGRAM, "", 10000).output, std::string("NO"));
    const VmResult r{ runVm(PROGRAM, "4271", 10000) };
    CHECK(r.halted); CHECK(!r.error);
}
TEST("errors and runaway programs") {
    const VmResult bad{ runVm({ 0x0F }, "", 100) };
    CHECK(bad.error); CHECK(!bad.halted); CHECK_EQ(bad.steps, 0);
    CHECK(runVm({ 0x01, 0x09, 0x00, 0x00 }, "", 100).error);
    CHECK(runVm({ 0x09, 0x50, 0x00 }, "", 100).error);
    CHECK(runVm({ 0x01, 0x00, 0x01, 0x00 }, "", 100).error);
    const VmResult loop{ runVm({ 0x09, 0x00, 0x00 }, "", 100) };
    CHECK(!loop.error); CHECK(!loop.halted); CHECK_EQ(loop.steps, 100);
}
TEST("arithmetic wraps") {
    const Bytes p{ 0x01, 0x00, 0x00, 0x00, 0x01, 0x01, 0x01, 0x00, 0x04, 0x00, 0x01, 0x01, 0x02, 0xFF, 0x00, 0x07, 0x00, 0x41, 0x00, 0x0E, 0x00, 0x00 };
    const VmResult r{ runVm(p, "", 100) };
    CHECK(r.halted);
    CHECK_EQ(r.output, std::string("A"));
}
TEST("every accepted key") {
    CHECK_EQ(findKeys(PROGRAM), (std::vector<std::string>{ "4181", "4271" }));
}

